import{z as E,x as A,o as l,c as m,q as n,j as o,D as t,d as e,s as i,S as d,b as r}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"莫队算法","description":"","frontmatter":{"title":"莫队算法","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mo-algorithm.md","filePath":"cs/mo-algorithm.md","lastUpdated":1791063341000}'),B={name:"cs/mo-algorithm.md"};function p(h,a,c,D,f,_){const s=A("Mermaid");return l(),m("div",null,[a[2]||(a[2]=n('<h1 id="莫队算法" tabindex="-1">莫队算法 <a class="header-anchor" href="#莫队算法" aria-label="Permalink to &quot;莫队算法&quot;">​</a></h1><div class="epigraph"><p>区间不能随问随答时，把所有询问按左端所在块排序、块内按右端排序，让指针每次只小步扩缩。</p><footer>—— 据 Sedgewick and Wayne 对离线与分块的整理；竞赛文献中的 Mo&#39;s algorithm（莫涛）与分块排序</footer></div><p><a href="/cs/sqrt-decomposition">上一课</a>的在线分块要求「加一个点、去一个点」的代价能收进摘要。若只有「把区间从 \\([l,r]\\) 扩成 \\([l,r+1]\\)」这类 \\(\\mathrm{add}/\\mathrm{del}\\) 便宜、却没有对数树，可以把<strong>询问离线</strong>重排。本课不重定义块长。缺口是莫队：对静态数组、可加减的区间状态，用块序最小化指针移动。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(m\\) 个询问 \\([l_i,r_i]\\)，数组不变。维护当前 \\([L,R]\\) 上的状态（如不同颜色数），\\(\\mathrm{add}(i)\\)、\\(\\mathrm{del}(i)\\) 为 \\(O(1)\\) 或 \\(O(\\log n)\\)。若按输入顺序跳，指针总移动可到 \\(\\Theta(nm)\\)。莫队：块大小 \\(B\\)，询问按 \\((\\lfloor l/B\\rfloor,\\, r)\\) 排序（偶数块 \\(r\\) 反转可再省常数）。相邻询问的 \\(L,R\\) 变化合计 \\(O(n\\sqrt{m})\\) 量级（\\(m\\sim n\\)、\\(B\\sim n/\\sqrt{m}\\) 时常见 \\(O(n\\sqrt{n})\\)）。缺口不是新状态机，而是<strong>离线重排降低扩缩次数</strong>。</p><p><span class="marginnote">名称来自莫涛对分块排序技巧的普及。奇偶块翻转右端，减少块间 \\(R\\) 来回扫，是同一分析下的常数优化。</span></p><p><span class="marginnote">可以把它想象成图书管理员回答一叠「第 \\(x\\) 页到第 \\(y\\) 页有多少插图」的问题：他不每次从第一页翻起，而是把问题按页码分块排序，让书签只小步前挪后缩，顺手增删计数。莫队做的正是这件事，只是书签有两个。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读入全部询问，排序，从空或任意区间出发，对每个询问 while 扩缩 \\(L,R\\) 到目标，再记录答案。必须能逆：扩与缩都要正确，不能只 add 不能 del。</p><p><span class="marginnote">初学者容易只写 add 不写 del：往桶里 \\(+1\\) 容易，撤销时忘了把「恰好出现一次」这类计数同步 \\(-1\\)，答案就悄悄错掉。扩与缩必须互为逆操作，这是指针敢来回移动的前提。</span></p>',10)),(l(),o(d,null,{default:t(()=>[i(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20OFF%5B%22%E7%A6%BB%E7%BA%BF%E5%85%A8%E9%83%A8%20%5Bl%2C%20r%5D%5D%20--%3E%20SORT%5B%E6%8C%89%E5%B7%A6%E5%9D%97%2C%20%E5%86%8D%E6%8C%89%20r%22%5D%0A%20%20SORT%20--%3E%20PTR%5B%22%E6%8C%87%E9%92%88%20L%2C%20R%20%E6%89%A9%E7%BC%A9%22%5D%0A%20%20PTR%20--%3E%20ADD%5B%22add%20%2F%20del%20%E7%BB%B4%E6%8A%A4%E7%8A%B6%E6%80%81%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("p",null,"带修改莫队多一维时间块，复杂度更高，本课只钉静态。树上莫队把欧拉序当序列，机制仍是扩缩，本课不写。",-1)),a[4]||(a[4]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=r("p",null,[e("分析：左端每次询问最多动 \\(O(B)\\)，共 \\(O(mB)\\)；右端在同一块内单调，块间重置，共 \\(O(n\\cdot n/B)\\) 一类界。取 \\(B\\approx n/\\sqrt{m}\\) 平衡。这是"),r("a",{href:"/cs/amortized-analysis"},"摊还"),e("合计，不是单次询问对数。")],-1)),(l(),o(d,null,{default:t(()=>[i(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22m%20%E4%B8%AA%E8%AF%A2%E9%97%AE%22%5D%20--%3E%20L%5B%22%E5%B7%A6%E7%AB%AF%20L%3A%20%E6%AF%8F%E9%97%AE%E6%9C%80%E5%A4%9A%E5%8A%A8%20O(B)%20%E6%AD%A5%22%5D%0A%20%20Q%20--%3E%20R%5B%22%E5%8F%B3%E7%AB%AF%20R%3A%20%E5%9D%97%E5%86%85%E5%8D%95%E8%B0%83%2C%20%E5%9D%97%E9%97%B4%E9%87%8D%E7%BD%AE%22%5D%0A%20%20L%20--%3E%20LC%5B%22%E5%90%88%E8%AE%A1%20O(mB)%22%5D%0A%20%20R%20--%3E%20RC%5B%22%E5%90%88%E8%AE%A1%20O(n%C2%B7n%2FB)%22%5D%0A%20%20LC%20--%3E%20BAL%5B%22%E5%8F%96%20B%20%E2%89%88%20n%2F%E2%88%9Am%20%E8%AE%A9%E4%B8%A4%E9%A1%B9%E7%9B%B8%E7%AD%89%22%5D%0A%20%20RC%20--%3E%20BAL%0A%20%20BAL%20--%3E%20TOT%5B%22%E6%80%BB%E7%A7%BB%E5%8A%A8%20O(n%E2%88%9Am)%20%E9%87%8F%E7%BA%A7%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">代入数字感受一下：\\(n=m=10^5\\) 时 \\(B\\approx 316\\)，左端每个询问最多挪 316 步、合计约 \\(3\\times 10^7\\)；右端整程也只扫同一量级，总计约 \\(6\\times 10^7\\) 次单步操作——比按输入顺序最坏的 \\(10^{10}\\) 步省了两个数量级以上。</span></p><p>状态必须是「区间的可加减函数」。中位数若不能 \\(O(1)\\) add/del，莫队帮不上，应换权值树或排序分块。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>在线算法不能用莫队（必须先收齐询问）。不可逆状态、强制在线、或修改穿插过多时退回树。不要把莫队写成「所有区间问题的默认解」。</p><p>区间查询课序还剩紧凑的位级集合表示：位图与稀疏集合，不是再一张排序表。</p><p>后课默认：静态离线、状态可加减，可按块序扩缩。位级并行的集合用 bitset。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>莫队：离线按块排序，指针扩缩均摊近 \\(O(n\\sqrt{n})\\)。</li><li>要 add 与 del；数组静态。</li><li>位级集合是下一结构，不是另一套莫队。</li><li>出处：分块排序技巧；Sedgewick and Wayne；莫队作为该技巧的通行名。</li></ul>',8))])}const g=E(B,[["render",p]]);export{T as __pageData,g as default};
